using System.IO;using UnityEngine;using UnityEditor;
namespace LWS.TruckFishing.Editor {
public static class FishingPreviewAuthoring {
 public static void Create(FishingMatch match){var models=new GameObject[5];for(int i=0;i<models.Length;i++){models[i]=(GameObject)PrefabUtility.InstantiatePrefab(match.streams[0].fishPrefabs[i%3]);models[i].transform.SetParent(match.streams[0].transform,false);models[i].transform.localPosition=new Vector3(i%2==0?-2.6f:2.4f,.13f,3+i*3.5f);models[i].transform.localRotation=Quaternion.Euler(0,180-i*7,0);}var camera=match.streamCameras[0].view;var old=camera.targetTexture;var active=RenderTexture.active;foreach(int width in new[]{1280,1920,512}){int height=width*9/16;var rt=new RenderTexture(width,height,24);rt.Create();camera.targetTexture=rt;match.framing[0].Apply();camera.Render();RenderTexture.active=rt;var picture=new Texture2D(width,height,TextureFormat.RGB24,false);picture.ReadPixels(new Rect(0,0,width,height),0,0);picture.Apply();string path=width==512?"Assets/TruckFishing/Art/Menu Preview.png":"Logs/TruckSports/SevenSports/FishingWater/final-"+width+".png";Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,picture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(picture);camera.targetTexture=old;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}foreach(var model in models)UnityEngine.Object.DestroyImmediate(model);string preview="Assets/TruckFishing/Art/Menu Preview.png";AssetDatabase.ImportAsset(preview);var importer=(TextureImporter)AssetImporter.GetAtPath(preview);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.SaveAndReimport();match.framing[0].Apply();}
}
}
